      const due = claimDue(c, rateOn(rates, gradeOn(person, c.date), c.date, c.id), floor, late);
      buckets[age <= 30 ? 0 : age <= 60 ? 1 : 2].push(due);
    }
  }
  return [sumDue(buckets[0]), sumDue(buckets[1]), sumDue(buckets[2])];
}

